// WP-4.5 GPU post stack: see include/fuse/renderer/postprocess/gpu/post_stack_gpu.hpp.
#include <fuse/renderer/postprocess/gpu/post_stack_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>
#include <initializer_list>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp45.cmake from shaders/post/*: kPp<Kernel><Slang|Glsl>Spv and
// FUSE_POST_GPU_{SLANG,GLSL} when every kernel of a language exists.
#include "post_gpu_spv.h"
#endif

namespace fuse::renderer::post_gpu {

namespace {
constexpr u32 kPushBytes = sizeof(PostPush);
constexpr u32 kFrameStride = 512u; ///< ring slot size (>= sizeof(PostFrameConstants), 256-aligned)
static_assert(sizeof(PostFrameConstants) <= kFrameStride, "frame ring slot");
constexpr u32 kOutputFormat = static_cast<u32>(GpuFormat::R16G16B16A16Sfloat);
constexpr u64 kTexel = 16u; ///< f32x4
constexpr u64 kPair = 8u;   ///< f32x2

BufferUsage bufferUsage(std::initializer_list<BufferUsage> bits) {
    u32 u = 0;
    for (const BufferUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<BufferUsage>(u);
}

ImageUsage imageUsage(std::initializer_list<ImageUsage> bits) {
    u32 u = 0;
    for (const ImageUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<ImageUsage>(u);
}

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

PostBufferLayout PostBufferLayout::compute(u32 width, u32 height) {
    PostBufferLayout l{};
    u64 cursor = 0;
    auto take = [&](u64 bytes) {
        const u64 at = cursor;
        cursor = align256(cursor + std::max<u64>(bytes, 16u));
        return at;
    };
    const u64 n = static_cast<u64>(width) * height;
    l.hdr[0] = take(n * kTexel);
    l.hdr[1] = take(n * kTexel);
    // Pyramid extents: bloom_level_count semantics (halve, rounding up, until 1 x 1).
    u32 w = width;
    u32 h = height;
    for (u32 level = 0; level < kPostMaxBloomLevels; ++level) {
        l.levelW[level] = w;
        l.levelH[level] = h;
        l.down[level] = take(static_cast<u64>(w) * h * kTexel);
        ++l.levels;
        if (w == 1u && h == 1u) {
            break;
        }
        w = (w + 1u) / 2u;
        h = (h + 1u) / 2u;
    }
    const u64 tmpTexels = std::max(static_cast<u64>((width + 1u) / 2u) * height, static_cast<u64>(width) * ((height + 1u) / 2u));
    l.tmp = take(tmpTexels * kTexel);
    const u64 upTexels = l.levels > 1u ? static_cast<u64>(l.levelW[1]) * l.levelH[1] : 1u;
    l.up[0] = take(upTexels * kTexel);
    l.up[1] = take(upTexels * kTexel);
    l.bloom = take(n * kTexel);
    l.cocs = take(n * kPair);
    l.tileMax = take(n * kPair); // tile size >= 1
    l.neighborMax = take(n * kPair);
    l.histGroupsX = groups(width, kPostHistTile);
    l.histGroups = l.histGroupsX * groups(height, kPostHistTile);
    l.histPartials = take(static_cast<u64>(l.histGroups) * kPostHistMaxBins * 4u);
    l.workBytes = cursor;
    return l;
}

PostCapabilities queryPostCapabilities(const VulkanDevice* device) {
    PostCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    VkFormatProperties props{};
    vkGetPhysicalDeviceFormatProperties(static_cast<VkPhysicalDevice>(device->nativePhysicalDevice()),
                                        static_cast<VkFormat>(kOutputFormat), &props);
    if ((props.optimalTilingFeatures & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT) == 0u) {
        c.reason = "RGBA16F storage images unsupported";
        return c;
    }
    c.post = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

PostStackGpu::~PostStackGpu() { destroy(); }

bool PostStackGpu::init(const PostStackGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u) {
        return false;
    }
    if (!queryPostCapabilities(desc.device).post) {
        return false;
    }
    m_retired.reserve(8);
    m_lutSlotRevision.assign(desc.framesInFlight, 0u);
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "post_stack_gpu.frame";
    BufferDesc state{};
    state.size = sizeof(PostExposureState);
    state.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferSrc});
    state.memoryUsage = MemoryUsage::GpuOnly;
    state.name = "post_stack_gpu.exposure_state";
    if (!m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr ||
        m_frameRing.deviceAddress == 0u || !m_desc.allocator->createBuffer(state, m_state) ||
        m_state.deviceAddress == 0u || !createPipelines()) {
        destroy();
        return false;
    }
    return true;
#else
    return false;
#endif
}

void PostStackGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    Retired current{};
    current.buffers[0] = m_work;
    current.buffers[1] = m_lutRing;
    current.image = m_output.image;
    current.slots[0] = m_output.slot;
    for (u32 i = 0; i < kInputCount; ++i) {
        current.slots[1u + i] = m_inputSlots[i];
    }
    destroyRetired(current);
    if (m_frameRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_frameRing);
    }
    if (m_state.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_state);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_work = Buffer{};
    m_workQueue = rg::kNoQueue;
    m_state = Buffer{};
    m_stateQueue = rg::kNoQueue;
    m_stateInitialized = false;
    m_resetPending = true;
    m_resetEv = 0.f;
    m_output = Output{};
    m_frameRing = Buffer{};
    m_frameAddress = 0;
    m_lutRing = Buffer{};
    m_lutRingSize = 0;
    m_lutSlotStride = 0;
    m_lutSlotRevision.clear();
    m_lutHost.clear();
    m_lutSize = 0;
    m_lutRevision = 0;
    m_retired.clear();
    for (u32 i = 0; i < kInputCount; ++i) {
        m_inputImages[i] = nullptr;
        m_inputSlots[i] = BindlessSlotHandle{};
        m_inputHandles[i] = 0u;
    }
    m_width = m_height = 0;
    m_layout = PostBufferLayout{};
    m_recordCount = 0;
    m_language = "none";
    m_stats = PostStats{};
    m_initialized = false;
}

bool PostStackGpu::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_POST_GPU_SLANG)
    if (m_desc.language == PostKernelLanguage::Auto || m_desc.language == PostKernelLanguage::Slang) {
        k[kLoad] = code(kPpLoadSlangSpv);
        k[kBloom] = code(kPpBloomSlangSpv);
        k[kDof] = code(kPpDofSlangSpv);
        k[kMotionBlur] = code(kPpMotionBlurSlangSpv);
        k[kExposure] = code(kPpExposureSlangSpv);
        k[kDisplay] = code(kPpDisplaySlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_POST_GPU_GLSL)
    if (!found && (m_desc.language == PostKernelLanguage::Auto || m_desc.language == PostKernelLanguage::Glsl)) {
        k[kLoad] = code(kPpLoadGlslSpv);
        k[kBloom] = code(kPpBloomGlslSpv);
        k[kDof] = code(kPpDofGlslSpv);
        k[kMotionBlur] = code(kPpMotionBlurGlslSpv);
        k[kExposure] = code(kPpExposureGlslSpv);
        k[kDisplay] = code(kPpDisplayGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    return false;
#endif
}

bool PostStackGpu::createWork(u32 width, u32 height) {
    const PostBufferLayout layout = PostBufferLayout::compute(width, height);
    BufferDesc work{};
    work.size = static_cast<usize>(layout.workBytes);
    work.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferSrc});
    work.memoryUsage = MemoryUsage::GpuOnly;
    work.name = "post_stack_gpu.work";
    Buffer fresh{};
    if (!m_desc.allocator->createBuffer(work, fresh) || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (m_work.handle != nullptr) {
        Retired old{};
        old.buffers[0] = m_work;
        retire(old);
    }
    m_work = fresh;
    m_workQueue = rg::kNoQueue;
    m_layout = layout;
    ++m_stats.workRebuilds;
    return true;
}

bool PostStackGpu::createOutput(u32 width, u32 height) {
    Output o{};
    TextureDesc d{};
    d.width = width;
    d.height = height;
    d.format = static_cast<GpuFormat>(kOutputFormat);
    d.usage = imageUsage({ImageUsage::Storage, ImageUsage::Sampled, ImageUsage::TransferSrc});
    d.name = "post_stack_gpu.output";
    if (!m_desc.allocator->createImage(d, o.image)) {
        return false;
    }
    o.slot = m_desc.bindless->registerTextureSlot(o.image, true);
    if (!o.slot.isValid()) {
        m_desc.allocator->destroyImage(o.image);
        return false;
    }
    if (m_output.image.image != nullptr) {
        Retired old{};
        old.image = m_output.image;
        old.slots[0] = m_output.slot;
        retire(old);
    }
    m_output = o;
    ++m_stats.outputRebuilds;
    return true;
}

bool PostStackGpu::bindInput(u32 index, const Texture* image) {
    void* handle = image != nullptr ? image->image : nullptr;
    if (handle == m_inputImages[index] && (handle == nullptr || m_inputSlots[index].isValid())) {
        return true;
    }
    if (m_inputSlots[index].isValid()) {
        Retired old{};
        old.slots[1u + index] = m_inputSlots[index];
        retire(old);
    }
    m_inputSlots[index] = BindlessSlotHandle{};
    m_inputImages[index] = nullptr;
    m_inputHandles[index] = 0u;
    if (handle == nullptr) {
        return true;
    }
    m_inputSlots[index] = m_desc.bindless->registerTextureSlot(*image, false);
    if (!m_inputSlots[index].isValid()) {
        return false;
    }
    m_inputImages[index] = handle;
    m_inputHandles[index] = m_desc.bindless->shaderHandle(m_inputSlots[index]);
    ++m_stats.inputBinds;
    return true;
}

void PostStackGpu::retire(Retired r) {
    r.serial = m_frameSerial;
    m_retired.push_back(r);
    ++m_stats.retired;
}

void PostStackGpu::destroyRetired(Retired& r) {
    for (BindlessSlotHandle& slot : r.slots) {
        if (slot.isValid()) {
            m_desc.bindless->unregisterSlot(slot);
        }
    }
    for (Buffer& b : r.buffers) {
        if (b.handle != nullptr) {
            m_desc.allocator->destroyBuffer(b);
        }
    }
    if (r.image.image != nullptr) {
        m_desc.allocator->destroyImage(r.image);
    }
    r = Retired{};
}

u32 PostStackGpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyRetired(m_retired[i]);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

void PostStackGpu::setGradeLut(const look::Lut3D* lut) {
    if (lut == nullptr || !lut->valid()) {
        m_lutSize = 0;
        ++m_lutRevision;
        return;
    }
    const usize entries = lut->data.size();
    m_lutHost.resize(entries * 4u);
    for (usize i = 0; i < entries; ++i) {
        m_lutHost[i * 4u + 0u] = lut->data[i].x;
        m_lutHost[i * 4u + 1u] = lut->data[i].y;
        m_lutHost[i * 4u + 2u] = lut->data[i].z;
        m_lutHost[i * 4u + 3u] = 0.f;
    }
    m_lutSize = lut->size;
    ++m_lutRevision;
}

void PostStackGpu::resetExposure(f32 ev) {
    m_resetPending = true;
    m_resetEv = ev;
}

bool PostStackGpu::writeLut(u32 slot) {
    const u64 bytes = static_cast<u64>(m_lutSize) * m_lutSize * m_lutSize * kTexel;
    if (m_lutRing.handle == nullptr || m_lutRingSize != m_lutSize) {
        BufferDesc d{};
        d.size = static_cast<usize>(align256(bytes) * m_desc.framesInFlight);
        d.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
        d.memoryUsage = MemoryUsage::CpuToGpu;
        d.name = "post_stack_gpu.lut";
        Buffer fresh{};
        if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
            if (fresh.handle != nullptr) {
                m_desc.allocator->destroyBuffer(fresh);
            }
            return false;
        }
        if (m_lutRing.handle != nullptr) {
            Retired old{};
            old.buffers[1] = m_lutRing;
            retire(old);
        }
        m_lutRing = fresh;
        m_lutRingSize = m_lutSize;
        m_lutSlotStride = align256(bytes);
        std::fill(m_lutSlotRevision.begin(), m_lutSlotRevision.end(), 0u);
        ++m_stats.lutRebuilds;
    }
    if (m_lutSlotRevision[slot] != m_lutRevision) {
        std::memcpy(static_cast<u8*>(m_lutRing.mapped) + slot * m_lutSlotStride, m_lutHost.data(), static_cast<usize>(bytes));
        m_lutSlotRevision[slot] = m_lutRevision;
        ++m_stats.lutUploads;
    }
    return true;
}

bool PostStackGpu::beginLookFrame(u64 frameSerial, const look::LookEffectGraph& graph, const look::LookResolved& look,
                                  u64 frameSeed, f32 deltaSeconds, const PostFrameImages& images) {
    PostGpuSettings settings{};
    u32 unsupported = 0;
    if (!settings_from_look(graph, look, frameSeed, deltaSeconds, settings, &unsupported)) {
        return false;
    }
    const bool ok = beginFrame(frameSerial, settings, images);
    m_stats.lookUnsupported = unsupported;
    return ok;
}

bool PostStackGpu::beginFrame(u64 frameSerial, const PostGpuSettings& settings, const PostFrameImages& images) {
    if (!m_initialized || images.hdr == nullptr || images.hdr->image == nullptr) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    m_stats.bloomLevels = 0;
    m_stats.lookUnsupported = 0;
    m_stats.dofRan = m_stats.motionBlurRan = m_stats.bloomRan = m_stats.exposureRan = m_stats.lutApplied = false;
    const u32 w = images.hdr->desc.width;
    const u32 h = images.hdr->desc.height;
    if (w == 0u || h == 0u) {
        return false;
    }
    if (w != m_width || h != m_height || m_work.handle == nullptr || m_output.image.image == nullptr) {
        if (!createWork(w, h) || !createOutput(w, h)) {
            return false;
        }
        m_width = w;
        m_height = h;
    }
    const Texture* inputs[kInputCount] = {images.hdr, images.depth, images.velocity};
    for (u32 i = 0; i < kInputCount; ++i) {
        if (!bindInput(i, inputs[i])) {
            return false;
        }
    }
    m_settings = settings;
    m_hasDepth = m_inputHandles[1] != 0u;
    m_hasVelocity = m_inputHandles[2] != 0u;

    PostFrameConstants c{};
    resolve_constants(settings, c);
    const u64 work = m_work.deviceAddress;
    c.histPartials = work + m_layout.histPartials;
    c.exposureState = m_state.deviceAddress;
    c.dump = images.dumpAddress;
    c.cocs = work + m_layout.cocs;
    c.tileMax = work + m_layout.tileMax;
    c.neighborMax = work + m_layout.neighborMax;
    c.width = w;
    c.height = h;
    c.inputHdr = m_inputHandles[0];
    c.inputDepth = m_inputHandles[1];
    c.inputVelocity = m_inputHandles[2];
    c.output = m_desc.bindless->shaderHandle(m_output.slot);
    c.histGroupsX = m_layout.histGroupsX;
    c.histGroups = m_layout.histGroups;
    c.mbTilesX = groups(w, c.mbTile);
    c.mbTilesY = groups(h, c.mbTile);
    if (m_hasDepth) {
        c.flags |= kPostFlagMbDepth;
    }
    if (settings.autoExposure) {
        if (m_resetPending || !m_stateInitialized) {
            c.flags |= kPostFlagExposureReset;
            c.resetEv = m_resetPending ? m_resetEv : 0.f;
            m_resetPending = false;
            m_stateInitialized = true;
        }
    }
    const u32 slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    if (settings.lut && m_lutSize >= 2u) {
        if (!writeLut(slot)) {
            return false;
        }
        c.lut = m_lutRing.deviceAddress + slot * m_lutSlotStride;
        c.lutSize = m_lutSize;
        c.flags |= kPostFlagLut;
        m_stats.lutApplied = true;
    }
    m_constants = c;
    const u64 offset = static_cast<u64>(slot) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &c, sizeof(c));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    return true;
}

PostGraphRefs PostStackGpu::importInto(rg::Graph& graph) {
    PostGraphRefs refs{};
    if (!m_initialized || m_work.handle == nullptr) {
        return refs;
    }
    refs.work = graph.importBuffer(
        rg::ImportedBuffer{m_work.handle, m_work.desc.size, m_workQueue, &m_workQueue, "post_stack_gpu.work"});
    refs.state = graph.importBuffer(
        rg::ImportedBuffer{m_state.handle, m_state.desc.size, m_stateQueue, &m_stateQueue, "post_stack_gpu.exposure_state"});
    rg::ImportedImage i{};
    i.image = m_output.image.image;
    i.view = m_output.image.view;
    i.format = kOutputFormat;
    i.width = m_width;
    i.height = m_height;
    i.initialLayout = m_output.layout;
    i.initialQueue = m_output.queue;
    i.layoutTracker = &m_output.layout;
    i.queueTracker = &m_output.queue;
    i.name = "post_stack_gpu.output";
    refs.output = graph.importImage(i);
    return refs;
}

PostStackGpu::PassRecord* PostStackGpu::nextRecord(u32 kernel) {
    if (m_recordCount >= kMaxPasses) {
        return nullptr;
    }
    PassRecord* r = &m_records[m_recordCount++];
    *r = PassRecord{};
    r->self = this;
    r->kernel = kernel;
    r->push.frame = m_frameAddress;
    return r;
}

rg::PassBuilder PostStackGpu::addKernelPass(rg::Graph& graph, const char* name, PassRecord* r, const PostGraphRefs& refs) {
    ++m_stats.passes;
    rg::PassBuilder pass = graph.addPass(name, &PostStackGpu::recordDispatch, r);
    pass.use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    return pass;
}

void PostStackGpu::addPasses(rg::Graph& graph, const PostGraphRefs& refs, const PostGraphInputs& inputs) {
    if (!m_initialized || !refs.work.valid() || !refs.state.valid() || !refs.output.valid() || !inputs.hdr.valid()) {
        return;
    }
    const u32 w = m_width;
    const u32 h = m_height;
    const u64 base = m_work.deviceAddress;
    u32 cur = 0; // index into m_layout.hdr
    auto image = [&](PassRecord* r, u32 dw, u32 dh) {
        r->push.dstW = dw;
        r->push.dstH = dh;
        r->groups[0] = groups(dw, kPostTile);
        r->groups[1] = groups(dh, kPostTile);
    };
    auto pass = [&](u32 kernel, u32 mode) -> PassRecord* {
        PassRecord* r = nextRecord(kernel);
        if (r != nullptr) {
            r->push.mode = mode;
        }
        return r;
    };

    // post.load
    if (PassRecord* r = pass(kLoad, 0u)) {
        r->push.dst = base + m_layout.hdr[cur];
        image(r, w, h);
        addKernelPass(graph, "post.load", r, refs).use(inputs.hdr, rg::Access::SampledRead, {}, rg::kStageCompute);
    }

    // Spatial passes in the settings' order.
    for (u32 i = 0; i < m_settings.spatialCount; ++i) {
        switch (m_settings.spatialOrder[i]) {
        case PostSpatialPass::Bloom: {
            if (!m_settings.bloom) {
                break;
            }
            const u32 levels = bloom_levels(m_settings, w, h);
            if (m_recordCount + 4u * levels + 2u > kMaxPasses) {
                break;
            }
            m_stats.bloomLevels = levels;
            m_stats.bloomRan = true;
            const u64 hdr = base + m_layout.hdr[cur];
            PassRecord* r = pass(kBloom, kBloomPrefilter);
            r->push.src = hdr;
            r->push.dst = base + m_layout.down[0];
            image(r, w, h);
            addKernelPass(graph, "post.bloom.prefilter", r, refs);
            for (u32 l = 1; l < levels; ++l) {
                const u32 sw = m_layout.levelW[l - 1u];
                const u32 sh = m_layout.levelH[l - 1u];
                const u32 hw = (sw + 1u) / 2u;
                r = pass(kBloom, kBloomDownH);
                r->push.src = base + m_layout.down[l - 1u];
                r->push.dst = base + m_layout.tmp;
                r->push.srcW = sw;
                r->push.srcH = sh;
                image(r, hw, sh);
                addKernelPass(graph, "post.bloom.down_h", r, refs);
                r = pass(kBloom, kBloomDownV);
                r->push.src = base + m_layout.tmp;
                r->push.dst = base + m_layout.down[l];
                r->push.srcW = hw;
                r->push.srcH = sh;
                image(r, m_layout.levelW[l], m_layout.levelH[l]);
                addKernelPass(graph, "post.bloom.down_v", r, refs);
            }
            u64 up = base + m_layout.down[levels - 1u];
            u32 flip = 0;
            for (u32 level = levels - 1u; level > 0u; --level) {
                const u32 dst = level - 1u;
                const u32 sw = m_layout.levelW[level];
                const u32 sh = m_layout.levelH[level];
                const u32 dw = m_layout.levelW[dst];
                const u32 dh = m_layout.levelH[dst];
                r = pass(kBloom, kBloomUpH);
                r->push.src = up;
                r->push.dst = base + m_layout.tmp;
                r->push.srcW = sw;
                r->push.srcH = sh;
                image(r, dw, sh);
                addKernelPass(graph, "post.bloom.up_h", r, refs);
                const u64 target = dst == 0u ? base + m_layout.bloom : base + m_layout.up[flip];
                flip ^= 1u;
                r = pass(kBloom, kBloomUpV);
                r->push.src = base + m_layout.tmp;
                r->push.dst = target;
                r->push.aux = base + m_layout.down[dst];
                r->push.srcW = dw;
                r->push.srcH = sh;
                image(r, dw, dh);
                addKernelPass(graph, "post.bloom.up_v", r, refs);
                up = target;
            }
            r = pass(kBloom, kBloomComposite);
            r->push.dst = hdr;
            r->push.aux = up; // levels == 1: the prefiltered level 0
            image(r, w, h);
            addKernelPass(graph, "post.bloom.composite", r, refs);
            break;
        }
        case PostSpatialPass::DepthOfField: {
            if (!m_settings.dof || !m_hasDepth || !inputs.depth.valid() || m_recordCount + 2u > kMaxPasses) {
                break;
            }
            m_stats.dofRan = true;
            PassRecord* r = pass(kDof, kDofCoc);
            image(r, w, h);
            addKernelPass(graph, "post.dof.coc", r, refs).use(inputs.depth, rg::Access::SampledRead, {}, rg::kStageCompute);
            r = pass(kDof, kDofGather);
            r->push.src = base + m_layout.hdr[cur];
            r->push.dst = base + m_layout.hdr[cur ^ 1u];
            image(r, w, h);
            addKernelPass(graph, "post.dof.gather", r, refs);
            cur ^= 1u;
            break;
        }
        case PostSpatialPass::MotionBlur: {
            if (!m_settings.motionBlur || !m_hasVelocity || !inputs.velocity.valid() || m_recordCount + 3u > kMaxPasses) {
                break;
            }
            m_stats.motionBlurRan = true;
            const bool depth = m_hasDepth && inputs.depth.valid();
            PassRecord* r = pass(kMotionBlur, kMbTileMax);
            image(r, m_constants.mbTilesX, m_constants.mbTilesY);
            addKernelPass(graph, "post.mb.tile", r, refs)
                .use(inputs.velocity, rg::Access::SampledRead, {}, rg::kStageCompute);
            r = pass(kMotionBlur, kMbNeighborMax);
            image(r, m_constants.mbTilesX, m_constants.mbTilesY);
            addKernelPass(graph, "post.mb.neighbor", r, refs);
            r = pass(kMotionBlur, kMbGather);
            r->push.src = base + m_layout.hdr[cur];
            r->push.dst = base + m_layout.hdr[cur ^ 1u];
            image(r, w, h);
            rg::PassBuilder gather = addKernelPass(graph, "post.mb.gather", r, refs);
            gather.use(inputs.velocity, rg::Access::SampledRead, {}, rg::kStageCompute);
            if (depth) {
                gather.use(inputs.depth, rg::Access::SampledRead, {}, rg::kStageCompute);
            }
            cur ^= 1u;
            break;
        }
        }
    }
    m_displayInput = m_layout.hdr[cur];

    // Exposure: histogram of the display input + adaptation (GPU state).
    if (m_settings.autoExposure && m_recordCount + 3u <= kMaxPasses) {
        m_stats.exposureRan = true;
        PassRecord* r = pass(kExposure, kExposureHistogram);
        r->push.src = base + m_layout.hdr[cur];
        r->groups[0] = m_layout.histGroups;
        addKernelPass(graph, "post.exposure.histogram", r, refs);
        r = pass(kExposure, kExposureAdapt);
        r->groups[0] = 1u;
        ++m_stats.passes;
        graph.addPass("post.exposure.adapt", &PostStackGpu::recordDispatch, r)
            .use(refs.work, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(refs.state, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }

    // post.display
    if (PassRecord* r = pass(kDisplay, 0u)) {
        r->push.src = base + m_layout.hdr[cur];
        image(r, w, h);
        ++m_stats.passes;
        rg::PassBuilder display = graph.addPass("post.display", &PostStackGpu::recordDispatch, r);
        display.use(refs.work, rg::Access::StorageRead, {}, rg::kStageCompute);
        if (m_settings.autoExposure) {
            display.use(refs.state, rg::Access::StorageRead, {}, rg::kStageCompute);
        }
        display.use(refs.output, rg::Access::StorageWrite, {}, rg::kStageCompute);
        if (inputs.dump.valid()) {
            display.use(inputs.dump, rg::Access::StorageWrite,
                        rg::BufferRange{0, static_cast<u64>(w) * h * kTexel}, rg::kStageCompute);
        }
    }
}

u64 PostStackGpu::copyBytes(PostCopySource what) const {
    if (what == PostCopySource::ExposureState) {
        return sizeof(PostExposureState);
    }
    return static_cast<u64>(m_width) * m_height * kTexel;
}

void PostStackGpu::addCopy(rg::Graph& graph, const PostGraphRefs& refs, PostCopySource what, rg::BufferRef dst,
                           u64 dstOffset) {
    if (!m_initialized || !dst.valid()) {
        return;
    }
    PassRecord* r = nextRecord(kKernelCount);
    if (r == nullptr) {
        return;
    }
    r->copyBytes = copyBytes(what);
    r->copyDst = dstOffset;
    r->copyTo = dst;
    if (what == PostCopySource::ExposureState) {
        r->copyFrom = refs.state;
        r->copySrc = 0;
    } else {
        r->copyFrom = refs.work;
        if (what == PostCopySource::DisplayInput) {
            r->copySrc = m_displayInput;
        } else {
            r->copySrc = m_stats.bloomLevels > 1u ? m_layout.bloom : m_layout.down[0];
        }
    }
    if (!r->copyFrom.valid()) {
        return;
    }
    ++m_stats.passes;
    graph.addPass("post.copy", &PostStackGpu::recordCopy, r)
        .use(r->copyFrom, rg::Access::TransferSrc, rg::BufferRange{r->copySrc, r->copyBytes})
        .use(dst, rg::Access::TransferDst, rg::BufferRange{dstOffset, r->copyBytes});
}

void PostStackGpu::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const PostStackGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes,
                       &r.push);
    vkCmdDispatch(cmd, r.groups[0], r.groups[1], r.groups[2]);
#else
    (void)context;
    (void)user;
#endif
}

void PostStackGpu::recordCopy(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    const VkBufferCopy region{r.copySrc, r.copyDst, r.copyBytes};
    vkCmdCopyBuffer(cmd, static_cast<VkBuffer>(context.buffer(r.copyFrom)), static_cast<VkBuffer>(context.buffer(r.copyTo)),
                    1, &region);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::post_gpu
